#include <bits/stdc++.h>
using namespace std;
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n;if(!(cin>>n))return 0;vector<long long>a(n),b(n),da(n),db(n);for(auto &x:a)cin>>x;for(auto &x:b)cin>>x;if(n==1){cout<<0<<endl;return 0;}for(int i=0;i<n;i++){da[i]=a[(i+1)%n]-a[i];db[i]=b[(i+1)%n]-b[i];}vector<long long>pat=db;vector<int>pi(n);for(int i=1;i<n;i++){int j=pi[i-1];while(j&&pat[i]!=pat[j])j=pi[j-1];if(pat[i]==pat[j])j++;pi[i]=j;}int ans=-1;for(int i=0,j=0;i<2*n-1;i++){long long x=da[i%n];while(j&&x!=pat[j])j=pi[j-1];if(x==pat[j])j++;if(j==n){int st=i-n+1;if(st<n){ans=st;break;}j=pi[j-1];}}cout<<ans<<endl;return 0;}